components.css:
.ds-action-primary { display: inline-flex; align-items: center; gap: 12px; min-height: 44px; padding: 12px 19px; background: var(--ink, #1c2826); color: var(--paper, #f2f4f3); font-family: var(--sans, Archivo, system-ui, sans-serif); font-size: 15px; font-weight: 600; line-height: 1.2; text-decoration: none; border-radius: 0; }
.ds-action-primary:hover { background: var(--positive, #23543c); }
.ds-action-primary:focus-visible { outline: 2px solid var(--ink, #1c2826); outline-offset: 5px; }
.ds-icon { width: 18px; height: 18px; flex: 0 0 18px; stroke: currentColor; stroke-width: 1.7; fill: none; }

.ds-action-secondary { display: inline-flex; align-items: center; gap: 12px; min-height: 44px; color: var(--ink, #1c2826); font-family: var(--sans, Archivo, system-ui, sans-serif); font-size: 15px; font-weight: 600; line-height: 1.2; text-decoration: none; border-bottom: 1px solid var(--ink, #1c2826); }
.ds-action-secondary:focus-visible { outline: 2px solid var(--ink, #1c2826); outline-offset: 5px; }
.ds-icon { width: 18px; height: 18px; flex: 0 0 18px; stroke: currentColor; stroke-width: 1.7; fill: none; }

.ds-stage-stack { width: 100%; max-width: 382px; color: var(--ink, #1c2826); font-family: var(--sans, Archivo, system-ui, sans-serif); }
.ds-stage { display: flex; align-items: center; gap: 13px; width: 100%; min-height: 52px; padding: 12px 15px; background: transparent; color: inherit; border: 1px solid var(--line, #bac5bf); border-radius: 0; text-align: left; font: inherit; cursor: pointer; transition: background-color 180ms cubic-bezier(0.16, 1, 0.3, 1), border-color 180ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-stage:hover { background: #e8ece9; border-color: var(--muted, #53675e); }
.ds-stage[aria-pressed='true'] { background: var(--yellow, #d9ef57); border-color: var(--ink, #1c2826); }
.ds-stage:focus-visible { outline: 2px solid var(--ink, #1c2826); outline-offset: 5px; }
.ds-stage-symbol { display: inline-flex; align-items: center; justify-content: center; width: 25px; height: 25px; flex: 0 0 25px; border: 1px solid currentColor; font: 400 11px/1 var(--mono, 'Fragment Mono', monospace); }
.ds-stage-name { font-size: 16px; font-weight: 550; line-height: 1.3; }
.ds-stage-note { margin-left: auto; color: var(--muted, #53675e); font: 400 12px/1.5 var(--mono, 'Fragment Mono', monospace); text-align: right; }
.ds-connector { position: relative; height: 29px; }
.ds-connector::before { content: ''; position: absolute; top: 0; bottom: 0; left: 50%; border-left: 1px solid var(--ink, #1c2826); }
@media (prefers-reduced-motion: reduce) { .ds-stage { transition: none; } }

.ds-segmented { display: flex; border-bottom: 1px solid var(--ink, #1c2826); font-family: var(--sans, Archivo, system-ui, sans-serif); }
.ds-segmented button { background: none; border: 0; border-bottom: 3px solid transparent; margin-bottom: -1px; padding: 9px 13px; min-height: 44px; color: var(--ink, #1c2826); font-family: inherit; font-size: 13px; font-weight: 400; line-height: 1.2; cursor: pointer; }
.ds-segmented button[aria-pressed='true'] { border-bottom-color: var(--ink, #1c2826); font-weight: 650; }
.ds-segmented button:hover { background: #e6ebe7; }
.ds-segmented button:focus-visible { outline: 2px solid var(--ink, #1c2826); outline-offset: 5px; }

.ds-status-row { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; }
.ds-status { display: inline-flex; align-items: center; gap: 7px; padding: 6px 8px; border: 1px solid currentColor; border-radius: 0; font: 400 12px/1.5 var(--mono, 'Fragment Mono', monospace); letter-spacing: 0.025em; white-space: nowrap; }
.ds-status::before { content: ''; width: 5px; height: 5px; background: currentColor; flex: 0 0 5px; }
.ds-status--accepted { color: var(--positive, #23543c); }
.ds-status--rejected { color: var(--warning, #823b24); background: var(--warning-paper, #f1e3d9); }
.ds-status--diagnostic { color: var(--muted, #53675e); }

.ds-verdict { display: grid; grid-template-columns: 106px 1fr auto; gap: 24px; align-items: center; padding: 24px 28px; background: var(--yellow, #d9ef57); color: var(--ink, #1c2826); font-family: var(--sans, Archivo, system-ui, sans-serif); }
.ds-verdict-stamp { font: 400 12px/1.5 var(--mono, 'Fragment Mono', monospace); }
.ds-verdict p { margin: 0; max-width: none; font-size: 20px; line-height: 1.4; letter-spacing: -0.015em; }
.ds-verdict strong { font-weight: 650; }
.ds-verdict-link { display: flex; align-items: center; gap: 9px; color: inherit; font-size: 13px; white-space: nowrap; text-underline-offset: 0.22em; text-decoration-thickness: 1px; }
.ds-verdict-link:hover { text-decoration-thickness: 2px; }
.ds-verdict-link:focus-visible { outline: 2px solid var(--ink, #1c2826); outline-offset: 5px; }
.ds-icon { width: 18px; height: 18px; flex: 0 0 18px; stroke: currentColor; stroke-width: 1.7; fill: none; }
@media (max-width: 760px) { .ds-verdict { grid-template-columns: 1fr; gap: 13px 18px; padding: 22px 20px; } }

.ds-duration-table { width: 100%; border-collapse: collapse; font-family: var(--sans, Archivo, system-ui, sans-serif); color: var(--ink, #1c2826); }
.ds-duration-table th { padding-bottom: 15px; text-align: left; font-size: 12px; font-weight: 400; color: var(--muted, #53675e); }
.ds-duration-table th:first-child { width: 24%; }
.ds-duration-table th:last-child { text-align: right; }
.ds-duration-table td { padding: 15px 0; border-top: 1px solid var(--line, #bac5bf); font-size: 14px; vertical-align: middle; }
.ds-bar-cell { width: 50%; padding-inline: 8px 20px; }
.ds-duration-bar { display: block; height: 29px; min-width: 2px; width: 100%; transform: scaleX(var(--duration-ratio, 1)); transform-origin: left center; background: var(--ink, #1c2826); transition: transform 500ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-duration-bar--accepted { background: var(--yellow, #d9ef57); border: 1px solid var(--ink, #1c2826); }
.ds-duration { font: 400 15px/1 var(--mono, 'Fragment Mono', monospace); white-space: nowrap; text-align: right; }
.ds-sr-only { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); }
@media (prefers-reduced-motion: reduce) { .ds-duration-bar { transition: none; } }

.ds-experiment { border-top: 1px solid var(--line, #bac5bf); border-bottom: 1px solid var(--line, #bac5bf); color: var(--ink, #1c2826); font-family: var(--sans, Archivo, system-ui, sans-serif); }
.ds-experiment summary { display: grid; grid-template-columns: 70px 1fr auto 22px; gap: 16px; align-items: center; list-style: none; padding: 25px 0; cursor: pointer; }
.ds-experiment summary::-webkit-details-marker { display: none; }
.ds-experiment summary:hover .ds-exp-title { text-decoration: underline; text-underline-offset: 5px; }
.ds-exp-id { font: 400 13px/1.5 var(--mono, 'Fragment Mono', monospace); color: var(--muted, #53675e); }
.ds-exp-title { font-size: 24px; font-weight: 550; line-height: 1.25; letter-spacing: -0.02em; }
.ds-exp-status { padding: 6px 8px; border: 1px solid currentColor; color: var(--warning, #823b24); background: var(--warning-paper, #f1e3d9); font: 400 12px/1.5 var(--mono, 'Fragment Mono', monospace); letter-spacing: 0.025em; white-space: nowrap; }
.ds-exp-plus { position: relative; width: 18px; height: 18px; }
.ds-exp-plus::before, .ds-exp-plus::after { content: ''; position: absolute; background: var(--ink, #1c2826); }
.ds-exp-plus::before { left: 0; right: 0; top: 8px; height: 1px; }
.ds-exp-plus::after { top: 0; bottom: 0; left: 8px; width: 1px; }
.ds-experiment[open] .ds-exp-plus::after { display: none; }
.ds-exp-body { padding: 2px 38px 32px 86px; max-width: 69ch; color: var(--muted, #53675e); font-size: 15px; line-height: 1.6; }
@media (max-width: 760px) { .ds-experiment summary { grid-template-columns: 45px 1fr 18px; gap: 10px; padding-block: 23px; } .ds-exp-title { font-size: 20px; } .ds-exp-status { grid-column: 2; grid-row: 2; justify-self: start; } .ds-exp-plus { grid-column: 3; grid-row: 1 / 3; } .ds-exp-body { padding: 3px 0 26px 0; } }
